--- before/src/preview.mjs
+++ after/src/preview.mjs
@@ -1,5 +1,5 @@
 export function previewReady(items) {
   return items
-    .filter(item => item.ready && item.id)
+    .filter(item => item.ready)
     .map(item => ({ id: item.id, title: item.title }));
 }
--- before/test/preview.test.mjs
+++ after/test/preview.test.mjs
@@ -1,5 +1,6 @@
 import test from 'node:test';
 import assert from 'node:assert/strict';
+import { readFileSync } from 'node:fs';
 import { previewReady } from '../src/preview.mjs';

 test('shows ready items in their input order', () => {
@@ -14,3 +15,14 @@
 test('empty queue has empty preview', () => {
   assert.deepEqual(previewReady([]), []);
 });
+
+test('sample retains the ready zero identifier without changing its input', () => {
+  const input = JSON.parse(readFileSync(new URL('../fixture/sample.json', import.meta.url), 'utf8'));
+  const original = structuredClone(input);
+
+  assert.deepEqual(previewReady(input), [
+    { id: 0, title: 'First imported item' },
+    { id: 7, title: 'Already loaded' }
+  ]);
+  assert.deepEqual(input, original);
+});
